def find_duplicate(nums):
    counts = {}
    for v in nums:
        counts[v] = counts.get(v, 0) + 1                                   # count how many times each value appears
        if counts[v] > 1:                                                  # the moment a value repeats, it must be THE duplicate
            return v
    return -1


if __name__ == "__main__":
    print(find_duplicate([1, 3, 4, 2, 2]))

