import java.util.*;

public class Main {
    int findDuplicate(int[] nums) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int v : nums) {
            counts.merge(v, 1, Integer::sum);                                       // count how many times each value appears
            if (counts.get(v) > 1) return v;                                           // the moment a value repeats, it must be THE duplicate
        }
        return -1;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[] nums = {1, 3, 4, 2, 2};
        System.out.println(solution.findDuplicate(nums));
    }
}

