#include <bits/stdc++.h>
using namespace std;

int findDuplicate(vector<int>& nums) {
    unordered_map<int, int> counts;
    for (int v : nums) {
        counts[v]++;                                                                  // count how many times each value appears
        if (counts[v] > 1) return v;                                                     // the moment a value repeats, it must be THE duplicate
    }
    return -1;
}

int main() {
    vector<int> nums = {1, 3, 4, 2, 2};
    cout << findDuplicate(nums) << endl;
    return 0;
}

