import java.util.*;

public class Main {
    int findDuplicate(int[] nums) {
        int slow = nums[0];                                                          // phase 1: detect the cycle (treating index -> nums[index] as "next")
        int fast = nums[nums[0]];
        while (slow != fast) {
            slow = nums[slow];
            fast = nums[nums[fast]];
        }

        int ptr1 = 0;                                                                   // phase 2: locate the cycle's entrance (same trick as Linked List Cycle II)
        int ptr2 = slow;
        while (ptr1 != ptr2) {
            ptr1 = nums[ptr1];
            ptr2 = nums[ptr2];
        }
        return ptr1;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[] nums = {1, 3, 4, 2, 2};
        System.out.println(solution.findDuplicate(nums));
    }
}

